# --- Sidebar ke links dhoondo, taaki dashboard ke buttons sahi page kholein ---
function Get-RoutePath([string]$PageFile) {
    $dir = Split-Path $PageFile
    $rel = $dir.Substring($AppDir.Length).Replace("\", "/")
    $parts = $rel.Split("/") | Where-Object { $_ -and -not ($_ -match '^\(.*\)$') }
    return "/" + ($parts -join "/")
}

$AllPages = @(Find-ProjectFiles "page.tsx") + @(Find-ProjectFiles "page.jsx") + @(Find-ProjectFiles "page.js") |
    Where-Object { $_.FullName.StartsWith($AppDir) }
$AllRoutes = @($AllPages | ForEach-Object { Get-RoutePath $_.FullName })

function Pick-Route([string[]]$Candidates) {
    foreach ($c in $Candidates) { if ($AllRoutes -contains $c) { return $c } }
    return $null
}

$ProcessingRoute = $null
foreach ($p in $AllPages) {
    $c = Get-Content -LiteralPath $p.FullName -Raw
    if ($c -match "orders-panel") { $ProcessingRoute = Get-RoutePath $p.FullName; break }
}
if (-not $ProcessingRoute) { $ProcessingRoute = Pick-Route @("/processing", "/admin/processing", "/processing/dashboard", "/processing/orders") }

$Links = [ordered]@{
    orders     = Pick-Route @("/admin/orders", "/orders")
    processing = $ProcessingRoute
    delivery   = Pick-Route @("/admin/delivery-control", "/admin/delivery", "/admin/delivery-dashboard", "/admin/delivery-control-tower", "/delivery-control")
    riders     = Pick-Route @("/admin/rider-approvals", "/admin/riders", "/admin/rider-list", "/admin/delivery-riders")
    inventory  = Pick-Route @("/admin/inventory", "/inventory")
    customers  = Pick-Route @("/admin/customers", "/customers")
}
$LinkLines = @()
foreach ($k in $Links.Keys) {
    if ($Links[$k]) { $LinkLines += "        ${k}: `"$($Links[$k])`"," ; Say ("  link    {0,-10} -> {1}" -f $k, $Links[$k]) Gray }
    else { $LinkLines += "        ${k}: null," }
}
$LinksBlock = $LinkLines -join "`r`n"

