$WrapperComponent = @"
import AdminLiveDashboard from "@/components/admin/live-dashboard";

// Fresh2Cook admin dashboard - live data from /api/admin/dashboard-live
// (purana dummy-data version _backups folder me hai)
export default function AdminDashboardContent(_props: Record<string, unknown>) {
