$pickupTargets = @()
foreach ($p in $AllPages) {
    $route = Get-RoutePath $p.FullName
    if (@("/rider/pickup-order", "/rider/pickup", "/rider-pickup") -contains $route) { $pickupTargets += $p.FullName }
}
if ($pickupTargets.Count -eq 0) { $pickupTargets += (Join-Path $AppDir "rider\pickup-order\page.tsx") }

foreach ($t in $pickupTargets) {
    if ($t -notlike "*.tsx") {
        $bk = Join-Path $BackupDir ($t.Substring($Root.Length).TrimStart("\"))
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Move-Item -LiteralPath $t -Destination $bk -Force
        $t = [IO.Path]::ChangeExtension($t, ".tsx")
    }
    Write-TextFile $t $PickupWrapper
}
Say "  OK      Pickup page ready:  localhost:3000/rider/pickup-order" Green

# ---------- 5e. v6: Settings, Admin OTP + All Pages, Customer account ----------
Say ""
Say "v7: Settings, Admin, Customer account, Home, Products, Policy pages..." White

foreach ($f in $V6Files) {
    $rel = $f.Path
    if ($rel.StartsWith("app\")) { $target = Join-Path $AppDir $rel.Substring(4) }
    else { $target = Join-Path $AliasBase $rel }
    Write-ProjectFile $target ($f.Data -join "")
}

# --- Database: nayi tables (AppSetting, CustomerAccount) ---
# Ab yeh tables app khud pehli baar use hone par bana leta hai (prisma generate ki zaroorat nahi).
# schema.prisma me models sirf record ke liye add kiye jaate hain.
$SchemaPath = Join-Path $Root "prisma\schema.prisma"
if (Test-Path $SchemaPath) {
    $schemaText = Get-Content -LiteralPath $SchemaPath -Raw
    if ($schemaText -notmatch "model\s+AppSetting\s*\{" -or $schemaText -notmatch "model\s+CustomerAccount\s*\{") {
        $bk = Join-Path $BackupDir "prisma\schema.prisma"
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Copy-Item -LiteralPath $SchemaPath -Destination $bk -Force
        $add = $Utf8NoBom.GetString([Convert]::FromBase64String(($B64_SCHEMA_ADD -join "")))
        [System.IO.File]::WriteAllText($SchemaPath, $schemaText.TrimEnd() + "`r`n" + $add, $Utf8NoBom)
        Say "  UPDATE  prisma\schema.prisma (AppSetting, CustomerAccount)" Green
    }
}
Say "  OK      Settings + Customer tables pehli baar page khulte hi apne aap ban jayengi" Green

# ---------- 6. Purana Next.js cache saaf ----------
$nextCache = Join-Path $Root ".next"
if (Test-Path $nextCache) {
    try {
        Remove-Item -LiteralPath $nextCache -Recurse -Force
        Say ""
        Say "Purana .next cache saaf kar diya." Gray
    } catch {
        Say ""
        Say "  .next cache saaf nahi hua (shayad server chal raha hai). Koi baat nahi." DarkYellow
    }
}

# ---------- 7. Summary ----------
Say ""
Say "==================== HO GAYA ====================" Green
Say ("Update hui files : " + $Updated.Count) Green
Say ("Nayi bani files  : " + $Created.Count) Yellow
if ($Skipped.Count -gt 0) { $Skipped | ForEach-Object { Say ("Skip             : " + $_) DarkYellow } }
if ($Updated.Count -gt 0) { Say ("Backup yahan hai : " + $BackupDir) Cyan }
Say ""
Say "Ab yeh karein:" White
Say "  1. Jis PowerShell/terminal me server chal raha hai, usme Ctrl + C dabayein." White
Say "  2. Phir chalayein:   npm run dev" White
Say "  3. Browser me localhost:3000/admin aur localhost:3000/rider/my-tasks, /rider/pickup-order kholein, Ctrl + F5 dabayein." White
Say "=================================================" Green
